CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Invoice" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Number" text,
    "CustomerID" integer NOT NULL,
    "Comment" text,
    "InternalComment" text,
    "SalesPerson" text,
    "Currency" text,
    "PurchaseOrderNumber" text,
    "Requisitioner" text,
    "ShippedVia" text,
    "FOB" text,
    "Terms" text,
    "BillingAddressRecipient" text,
    "BillingAddressCompany" text,
    "BillingAddressBuilding" text,
    "BillingAddressLine1" text,
    "BillingAddressLine2" text,
    "BillingAddressCity" text,
    "BillingAddressState" text,
    "BillingAddressPostalCode" text,
    "BillingAddressCountry" text,
    "ShippingAddressRecipient" text,
    "ShippingAddressRecipientTelephone" text,
    "ShippingAddressCompany" text,
    "ShippingAddressBuilding" text,
    "ShippingAddressLine1" text,
    "ShippingAddressLine2" text,
    "ShippingAddressCity" text,
    "ShippingAddressState" text,
    "ShippingAddressPostalCode" text,
    "ShippingAddressCountry" text,
    "CommercialRegistration" text,
    "TaxIdentification" text,
    "Subtotal" numeric(18,2),
    "VAT" numeric(18,2),
    "Total" numeric(18,2),
    "WithholdingTax" numeric(18,2),
    "Outstanding" numeric(18,2),
    "IsPaid" boolean NOT NULL,
    "ReceiptID" integer,
    "PaymentDate" timestamp with time zone,
    "CreatedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "ModifiedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Invoice" PRIMARY KEY ("ID")
);

CREATE TABLE "InvoiceFile" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceID" integer NOT NULL,
    "Bucket" text,
    "ObjectName" text,
    "CreatedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "ModifiedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_InvoiceFile" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_InvoiceFile_Invoice" FOREIGN KEY ("InvoiceID") REFERENCES "Invoice" ("ID")
);

CREATE TABLE "OrderItem" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceID" integer,
    "Description" text,
    "Quantity" integer,
    "UnitPrice" numeric(18,2),
    "Subtotal" numeric(18,2) GENERATED ALWAYS AS (("UnitPrice" * "Quantity")::numeric(18,2)) STORED,
    "CreatedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "ModifiedDate" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_OrderItem" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_OrderItem_Invoice" FOREIGN KEY ("InvoiceID") REFERENCES "Invoice" ("ID")
);

CREATE INDEX "IX_InvoiceFile_InvoiceID" ON "InvoiceFile" ("InvoiceID");

CREATE INDEX "IX_OrderItem_InvoiceID" ON "OrderItem" ("InvoiceID");

